package dev.bankledger.uploader;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.Map;
import org.junit.Test;

public class GrandExchangeSlotsTest {
  private static GrandExchangeSlots.Slot buying(int slot, int sold) {
    return new GrandExchangeSlots.Slot(slot, "BUYING", 385, 900, 1000, sold, sold * 900L);
  }

  @Test
  public void batchesChangesAndSkipsWhatTheSiteHas() {
    GrandExchangeSlots slots = new GrandExchangeSlots();
    assertTrue(slots.changed(buying(0, 0)));
    assertTrue(slots.changed(buying(0, 100))); // the newer one replaces it
    assertTrue(slots.changed(buying(3, 0)));
    List<GrandExchangeSlots.Slot> batch = slots.takeBatch();
    assertEquals(List.of(buying(0, 100), buying(3, 0)), batch);
    slots.accepted();

    // A login re-reports every slot: nothing new to send.
    assertFalse(slots.changed(buying(0, 100)));
    assertFalse(slots.changed(buying(3, 0)));
    assertNull(slots.takeBatch());
  }

  @Test
  public void oneBatchAtATime() {
    GrandExchangeSlots slots = new GrandExchangeSlots();
    slots.changed(buying(0, 0));
    slots.takeBatch();
    slots.changed(buying(1, 0));
    assertNull(slots.takeBatch());
    slots.accepted();
    assertEquals(List.of(buying(1, 0)), slots.takeBatch());
  }

  @Test
  public void aFailedBatchIsRetriedUnlessTheSlotMovedOn() {
    GrandExchangeSlots slots = new GrandExchangeSlots();
    slots.changed(buying(0, 0));
    slots.changed(buying(1, 0));
    slots.takeBatch();
    slots.changed(buying(1, 500)); // newer than what was in flight
    slots.failed();
    assertTrue(slots.hasPending());
    assertEquals(List.of(buying(0, 0), buying(1, 500)), slots.takeBatch());
  }

  @Test
  public void resetForgetsEverything() {
    GrandExchangeSlots slots = new GrandExchangeSlots();
    slots.changed(buying(0, 0));
    slots.takeBatch();
    slots.accepted();
    slots.reset();
    assertTrue(slots.changed(buying(0, 0)));
  }

  @Test
  public void buildsTheRequestBody() {
    Map<String, Object> body = GrandExchangeSlots.requestBody(List.of(
        new GrandExchangeSlots.Slot(2, "SELLING", 4151, 3_000_000_000L, 1, 0, 0)));
    assertEquals(1, body.get("version"));
    Map<?, ?> slot = (Map<?, ?>) ((List<?>) body.get("slots")).get(0);
    assertEquals(2, slot.get("slot"));
    assertEquals("SELLING", slot.get("state"));
    assertEquals(3_000_000_000L, slot.get("price"));
  }
}

package dev.bankledger.uploader;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class StoragePayloadTest {
  private static Map<String, Object> item(Number id, Number quantity) {
    Map<String, Object> m = new HashMap<>();
    m.put("id", id);
    m.put("quantity", quantity);
    return m;
  }

  private static Map<String, Object> storage(String category, String name, long lastUpdated, List<Map<String, Object>> items) {
    Map<String, Object> m = new HashMap<>();
    m.put("category", category);
    m.put("name", name);
    m.put("lastUpdated", lastUpdated);
    m.put("items", items);
    return m;
  }

  private static Map<String, Object> response(List<Map<String, Object>> storages) {
    Map<String, Object> data = new HashMap<>();
    data.put("source", "Dude, Where's My Stuff?");
    data.put("target", BankLedgerUploaderPlugin.SOURCE);
    data.put("version", 1);
    data.put("storages", storages);
    return data;
  }

  private static List<Map<String, Object>> bank(Object... idQty) {
    List<Map<String, Object>> items = new ArrayList<>();
    for (int i = 0; i < idQty.length; i += 2) {
      items.add(item((Number) idQty[i], (Number) idQty[i + 1]));
    }
    return items;
  }

  @Test
  public void sameBankSameFingerprintWhateverTheOrder() {
    StoragePayload a = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385, 10L, 995, 5000L)),
        storage("carryable", "Looting Bag", 1, bank(385, 2L)))));
    StoragePayload b = StoragePayload.fromResponse(response(List.of(
        storage("carryable", "Looting Bag", 1, bank(385, 2L)),
        storage("world", "Bank", 1, bank(995, 5000L, 385, 10L)))));
    assertEquals(a.fingerprint(), b.fingerprint());
  }

  @Test
  public void movingItemsBetweenStoragesIsNotAChange() {
    StoragePayload a = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385, 12L)))));
    StoragePayload b = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385, 10L)),
        storage("carryable", "Looting Bag", 1, bank(385, 2L)))));
    assertEquals(a.fingerprint(), b.fingerprint());
  }

  @Test
  public void quantityChangeChangesTheFingerprint() {
    StoragePayload a = StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 1, bank(385, 10L)))));
    StoragePayload b = StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 1, bank(385, 11L)))));
    assertNotEquals(a.fingerprint(), b.fingerprint());
  }

  @Test
  public void deathAndMinigameStoragesDontCountAsChanges() {
    StoragePayload a = StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 1, bank(385, 10L)))));
    StoragePayload b = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385, 10L)),
        storage("death", "Grave", 1, bank(4151, 1L)),
        storage("minigames", "Guardians of the Rift", 1, bank(556, 400L)))));
    assertEquals(a.fingerprint(), b.fingerprint());
  }

  @Test
  public void acceptsIntegerLongAndDoubleNumbers() {
    StoragePayload p = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385, 10, 995.0, 5000.0)))));
    StoragePayload q = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385L, 10L, 995, 5000L)))));
    assertEquals(p.fingerprint(), q.fingerprint());
  }

  @Test
  public void dropsEmptyAndInvalidItems() {
    StoragePayload p = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 1, bank(385, 0L, -1, 5L, 995, 10L)))));
    StoragePayload q = StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 1, bank(995, 10L)))));
    assertEquals(q.fingerprint(), p.fingerprint());
  }

  @Test
  public void requestBodyCarriesVersionStoragesAndOptionalPlayer() {
    StoragePayload p = StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 42, bank(385, 1L)))));
    Map<String, Object> body = p.toRequestBody(null, "1.0.0");
    assertEquals(1, body.get("version"));
    assertEquals("bank-ledger-uploader/1.0.0", body.get("client"));
    assertNull(body.get("player"));
    assertEquals("Zezima", p.toRequestBody("Zezima", "1.0.0").get("player"));
    @SuppressWarnings("unchecked")
    Map<String, Object> first = ((List<Map<String, Object>>) body.get("storages")).get(0);
    assertEquals(42L, first.get("lastUpdated"));
  }

  @Test(expected = IllegalArgumentException.class)
  public void refusesOtherVersions() {
    Map<String, Object> data = response(List.of());
    data.put("version", 2);
    StoragePayload.fromResponse(data);
  }

  @Test
  public void emptyWhenDwmsHasNothingYet() {
    assertTrue(StoragePayload.fromResponse(response(List.of())).isEmpty());
    assertFalse(StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 1, bank(1, 1L))))).isEmpty());
  }
}

package dev.bankledger.uploader;

import static org.junit.Assert.assertEquals;
import static org.junit.Assume.assumeTrue;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import org.junit.Test;

/**
 * Uploads through the plugin's real payload and client code to a running Bank Ledger. Skipped
 * unless pointed at one - use a local dev server and a throwaway profile:
 *
 * <pre>
 *   BANK_LEDGER_URL=http://127.0.0.1:8787 BANK_LEDGER_PROFILE=abcdefghij BANK_LEDGER_KEY=bl_... ./gradlew test
 * </pre>
 */
public class BankLedgerLiveTest {
  private static Map<String, Object> dwmsResponse(long sharks) {
    List<Map<String, Object>> items = new ArrayList<>();
    items.add(Map.of("id", 385, "quantity", sharks));
    items.add(Map.of("id", 995, "quantity", 250_000L));
    Map<String, Object> bank = new HashMap<>();
    bank.put("category", "world");
    bank.put("name", "Bank");
    bank.put("lastUpdated", System.currentTimeMillis());
    bank.put("items", items);
    Map<String, Object> grave = new HashMap<>();
    grave.put("category", "death");
    grave.put("name", "Grave");
    grave.put("lastUpdated", System.currentTimeMillis());
    grave.put("items", List.of(Map.of("id", 4151, "quantity", 1L)));

    Map<String, Object> data = new HashMap<>();
    data.put("version", 1);
    data.put("target", BankLedgerUploaderPlugin.SOURCE);
    data.put("storages", List.of(bank, grave));
    return data;
  }

  private static UploadResult send(BankLedgerClient client, HttpUrl url, String key, long sharks) throws Exception {
    CompletableFuture<UploadResult> result = new CompletableFuture<>();
    Map<String, Object> body = StoragePayload.fromResponse(dwmsResponse(sharks)).toRequestBody(null, "test");
    client.upload(url, key, body, result::complete);
    return result.get(30, TimeUnit.SECONDS);
  }

  @Test
  public void uploadsThenReportsUnchanged() throws Exception {
    String site = System.getenv("BANK_LEDGER_URL");
    String profile = System.getenv("BANK_LEDGER_PROFILE");
    String key = System.getenv("BANK_LEDGER_KEY");
    assumeTrue("set BANK_LEDGER_URL, BANK_LEDGER_PROFILE and BANK_LEDGER_KEY to run", site != null && profile != null && key != null);

    BankLedgerClient client = new BankLedgerClient(new OkHttpClient(), new Gson());
    HttpUrl url = BankLedgerClient.uploadUrl(site, profile);
    long sharks = 1000 + (System.currentTimeMillis() % 1000);

    assertEquals(UploadResult.Outcome.STORED, send(client, url, key, sharks).getOutcome());
    assertEquals(UploadResult.Outcome.UNCHANGED, send(client, url, key, sharks).getOutcome());
    assertEquals(UploadResult.Outcome.REJECTED, send(client, url, "bl_wrongwrongwrongwrongwrong", sharks + 1).getOutcome());
  }
}

package dev.bankledger.uploader;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import java.util.List;
import okhttp3.OkHttpClient;
import org.junit.Test;

public class BankLedgerClientTest {
  private final BankLedgerClient client = new BankLedgerClient(new OkHttpClient(), new Gson());

  @Test
  public void buildsTheUploadUrl() {
    assertEquals("https://bank-ledger.osrs-bank-tracker.workers.dev/api/u/abcde12345/storages",
        BankLedgerClient.uploadUrl(BankLedgerUploaderConfig.DEFAULT_SITE, "abcde12345").toString());
    assertEquals("https://example.com/api/u/abcdefghij/storages",
        BankLedgerClient.uploadUrl("https://example.com/some/path/", " abcdefghij ").toString());
  }

  @Test
  public void buildsTheGrandExchangeUrlOnTheSameTerms() {
    assertEquals("https://example.com/api/u/abcdefghij/ge-offers",
        BankLedgerClient.geOffersUrl("https://example.com", "abcdefghij").toString());
    assertNull(BankLedgerClient.geOffersUrl("http://example.com", "abcdefghij"));
  }

  @Test
  public void refusesBadIdsAndPlainHttp() {
    assertNull(BankLedgerClient.uploadUrl(BankLedgerUploaderConfig.DEFAULT_SITE, "short"));
    assertNull(BankLedgerClient.uploadUrl(BankLedgerUploaderConfig.DEFAULT_SITE, "ABCDEFGHIJ"));
    assertNull(BankLedgerClient.uploadUrl("http://example.com", "abcdefghij"));
    assertNull(BankLedgerClient.uploadUrl("not a url", "abcdefghij"));
  }

  @Test
  public void allowsALocalDevServerOverHttp() {
    assertEquals("http://127.0.0.1:8787/api/u/abcdefghij/storages",
        BankLedgerClient.uploadUrl("http://127.0.0.1:8787", "abcdefghij").toString());
  }

  @Test
  public void interpretsTheSitesReplies() {
    UploadResult stored = client.interpret(201, "{\"snapshotId\":3,\"actualWorth\":414000000,\"staleStorages\":[\"Seed Vault\"]}");
    assertEquals(UploadResult.Outcome.STORED, stored.getOutcome());
    assertEquals(414000000L, stored.getActualWorth());
    assertEquals(List.of("Seed Vault"), stored.getStaleStorages());

    assertEquals(UploadResult.Outcome.UNCHANGED, client.interpret(200, "{\"unchanged\":true,\"staleStorages\":[]}").getOutcome());
    assertEquals(UploadResult.Outcome.REJECTED, client.interpret(401, "{\"error\":\"This needs the profile's write key\"}").getOutcome());
    assertEquals(UploadResult.Outcome.REJECTED, client.interpret(404, "{\"error\":\"No such profile\"}").getOutcome());
    assertEquals(UploadResult.Outcome.DEFERRED, client.interpret(429, "{\"error\":\"slow down\"}").getOutcome());
    assertEquals(UploadResult.Outcome.DEFERRED, client.interpret(503, "{\"error\":\"read-only\"}").getOutcome());
    assertEquals(UploadResult.Outcome.FAILED, client.interpret(500, "not json").getOutcome());
  }
}

package dev.bankledger.uploader;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class UploadThrottleTest {
  private static final long MIN = 60_000;
  private static final long COOLDOWN = 10 * MIN;

  @Test
  public void firstUploadIsAlwaysAllowed() {
    assertTrue(new UploadThrottle().allows(5, COOLDOWN));
  }

  @Test
  public void changesDuringTheCooldownAreHeldThenSentOnce() {
    UploadThrottle t = new UploadThrottle();
    t.stored(0);
    // Back and forth between the bank and the GE: three changes in a few minutes.
    for (long at : new long[] {1 * MIN, 3 * MIN, 6 * MIN}) {
      assertFalse(t.allows(at, COOLDOWN));
      t.hold();
      assertFalse("not due during the cooldown", t.due(at, COOLDOWN));
    }
    assertTrue("due once the cooldown ends", t.due(10 * MIN, COOLDOWN));
    t.stored(10 * MIN); // the one merged upload
    assertFalse(t.due(11 * MIN, COOLDOWN));
    assertFalse(t.isHolding());
  }

  @Test
  public void nothingIsHeldWithoutAChange() {
    UploadThrottle t = new UploadThrottle();
    t.stored(0);
    assertFalse(t.due(30 * MIN, COOLDOWN));
  }

  @Test
  public void aChangeThatWasUndoneIsNotSent() {
    UploadThrottle t = new UploadThrottle();
    t.stored(0);
    t.hold();
    t.release(); // the bank went back to what was last sent
    assertFalse(t.due(30 * MIN, COOLDOWN));
  }

  @Test
  public void resetClearsTheCooldown() {
    UploadThrottle t = new UploadThrottle();
    t.stored(0);
    t.reset();
    assertTrue(t.allows(1, COOLDOWN));
  }
}

package dev.bankledger.uploader;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class GrandExchangeHoldingsTest {
  private static GrandExchangeHoldings.Offer offer(String state, int id, long price, int total, int sold) {
    return new GrandExchangeHoldings.Offer(state, id, price, total, sold);
  }

  private static Map<Integer, Long> asMap(List<Map<String, Object>> items) {
    Map<Integer, Long> m = new HashMap<>();
    for (Map<String, Object> it : items) {
      m.put((Integer) it.get("id"), (Long) it.get("quantity"));
    }
    return m;
  }

  @Test
  public void buyOffersHoldTheCoinsForTheUnfilledPart() {
    Map<Integer, Long> held = asMap(GrandExchangeHoldings.items(List.of(
        offer("BUYING", 4151, 1_500_000, 3, 1),        // 2 whips still to buy
        offer("CANCELLED_BUY", 385, 900, 1000, 400)))); // refund of 600 sharks' coins
    assertEquals(Map.of(995, 2 * 1_500_000L + 600 * 900L), held);
  }

  @Test
  public void buyPricesAboveTheOldIntLimitCount() {
    // RuneLite 1.13 made GrandExchangeOffer.getPrice() a long.
    Map<Integer, Long> held = asMap(GrandExchangeHoldings.items(List.of(
        offer("BUYING", 20997, 3_000_000_000L, 2, 0))));
    assertEquals(Map.of(995, 6_000_000_000L), held);
  }

  @Test
  public void sellOffersHoldTheUnsoldItems() {
    Map<Integer, Long> held = asMap(GrandExchangeHoldings.items(List.of(
        offer("SELLING", 385, 900, 1000, 250),
        offer("CANCELLED_SELL", 385, 950, 100, 0),
        offer("SELLING", 4151, 1_600_000, 1, 0))));
    assertEquals(Map.of(385, 850L, 4151, 1L), held);
  }

  @Test
  public void completedAndEmptySlotsHoldNothing() {
    assertTrue(GrandExchangeHoldings.items(List.of(
        offer("BOUGHT", 4151, 1_500_000, 1, 1),
        offer("SOLD", 385, 900, 100, 100),
        offer("EMPTY", 0, 0, 0, 0))).isEmpty());
  }

  @Test
  public void ignoresFullyFilledActiveOffersAndJunk() {
    assertTrue(GrandExchangeHoldings.items(List.of(
        offer("BUYING", 385, 900, 10, 10),
        offer("SELLING", -1, 900, 10, 0),
        offer("BUYING", 385, 0, 10, 0))).isEmpty());
  }

  private static Map<String, Object> response(List<Map<String, Object>> storages) {
    Map<String, Object> data = new HashMap<>();
    data.put("version", 1);
    data.put("storages", storages);
    return data;
  }

  private static Map<String, Object> storage(String category, String name, int id, long qty) {
    Map<String, Object> s = new HashMap<>();
    s.put("category", category);
    s.put("name", name);
    s.put("lastUpdated", 1L);
    List<Map<String, Object>> items = new ArrayList<>();
    items.add(Map.of("id", id, "quantity", qty));
    s.put("items", items);
    return s;
  }

  @Test
  public void replacesDwmsGrandExchangeStorageAndAddsTheOffers() {
    List<Map<String, Object>> dwms = List.of(
        storage("world", "Bank", 385, 100L),
        storage("coins", "Grand Exchange", 995, 540_000L));
    List<Map<String, Object>> ge = GrandExchangeHoldings.items(List.of(offer("CANCELLED_BUY", 385, 900, 600, 0)));

    StoragePayload withGe = StoragePayload.fromResponse(response(dwms), ge, 5L);
    @SuppressWarnings("unchecked")
    List<Map<String, Object>> sent = (List<Map<String, Object>>) withGe.toRequestBody(null, "t").get("storages");
    assertEquals(2, sent.size());
    assertEquals("Bank", sent.get(0).get("name"));
    assertEquals("Grand Exchange offers", sent.get(1).get("name"));
    assertEquals("ge", sent.get(1).get("category"));

    // Same bank, same offers: same fingerprint. The refund is counted once, not twice.
    StoragePayload bankOnly = StoragePayload.fromResponse(response(List.of(
        storage("world", "Bank", 385, 100L), storage("world", "Other", 995, 540_000L))));
    assertEquals(bankOnly.fingerprint(), withGe.fingerprint());
  }

  @Test
  public void listingItemsDoesNotLookLikeLosingThem() {
    // Before: 100 sharks in the bank. After: 60 in the bank, 40 listed for sale.
    StoragePayload before = StoragePayload.fromResponse(response(List.of(storage("world", "Bank", 385, 100L))), List.of(), 1L);
    StoragePayload after = StoragePayload.fromResponse(
        response(List.of(storage("world", "Bank", 385, 60L))),
        GrandExchangeHoldings.items(List.of(offer("SELLING", 385, 900, 40, 0))), 2L);
    assertEquals(before.fingerprint(), after.fingerprint());
  }

  @Test
  public void leavingOffersOutKeepsDwmsStorageAsIs() {
    StoragePayload p = StoragePayload.fromResponse(response(List.of(storage("coins", "Grand Exchange", 995, 10L))), null, 1L);
    StoragePayload q = StoragePayload.fromResponse(response(List.of(storage("coins", "Grand Exchange", 995, 11L))), null, 1L);
    assertNotEquals(p.fingerprint(), q.fingerprint());
  }
}

