package dev.bankledger.uploader;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Turns a Dude, Where's My Stuff "storages-response" plugin message into the body Bank Ledger's
 * /storages endpoint takes, and fingerprints the bank so an unchanged one is never re-sent.
 *
 * <p>Pure: no RuneLite types, so it is unit tested on its own.
 */
final class StoragePayload {
  static final int FORMAT_VERSION = 1;

  /**
   * Categories the server leaves out (death storages: items at risk, not held; minigames: point
   * counters that reuse item ids). Left out of the fingerprint too, so a new grave doesn't count as
   * a changed bank.
   */
  static final Set<String> SKIPPED_CATEGORIES = Set.of("death", "minigames");

  private final List<Map<String, Object>> storages;
  private final String fingerprint;

  private StoragePayload(List<Map<String, Object>> storages, String fingerprint) {
    this.storages = storages;
    this.fingerprint = fingerprint;
  }

  /**
   * Reads the "storages" list of a version 1 response. Values arrive as Object (the message map
   * is untyped), and numbers may be Integer, Long or Double depending on how they were boxed.
   *
   * @throws IllegalArgumentException if the response isn't a version 1 storage list
   */
  static StoragePayload fromResponse(Map<String, Object> data) {
    return fromResponse(data, null, 0);
  }

  /**
   * As above, plus what is locked in Grand Exchange offers (see {@link GrandExchangeHoldings}),
   * which replaces DWMS's own "Grand Exchange" coin storage. Null leaves the GE out entirely.
   */
  static StoragePayload fromResponse(
      Map<String, Object> data, List<Map<String, Object>> grandExchangeItems, long now) {
    Object version = data.get("version");
    if (!(version instanceof Number) || ((Number) version).intValue() != FORMAT_VERSION) {
      throw new IllegalArgumentException("Unsupported Dude, Where's My Stuff message version: " + version);
    }
    Object rawStorages = data.get("storages");
    if (!(rawStorages instanceof List)) {
      throw new IllegalArgumentException("No storage list in the response");
    }

    List<Object> all = new ArrayList<>((List<?>) rawStorages);
    if (grandExchangeItems != null) {
      all.removeIf(s -> s instanceof Map && GrandExchangeHoldings.isDwmsGrandExchange((Map<?, ?>) s));
      if (!grandExchangeItems.isEmpty()) {
        all.add(GrandExchangeHoldings.storage(grandExchangeItems, now));
      }
    }

    List<Map<String, Object>> storages = new ArrayList<>();
    TreeMap<Integer, Long> merged = new TreeMap<>();
    for (Object rawStorage : all) {
      if (!(rawStorage instanceof Map)) {
        continue;
      }
      Map<?, ?> storage = (Map<?, ?>) rawStorage;
      String category = String.valueOf(storage.get("category"));
      List<Map<String, Object>> items = new ArrayList<>();
      Object rawItems = storage.get("items");
      if (rawItems instanceof List) {
        for (Object rawItem : (List<?>) rawItems) {
          if (!(rawItem instanceof Map)) {
            continue;
          }
          Object id = ((Map<?, ?>) rawItem).get("id");
          Object quantity = ((Map<?, ?>) rawItem).get("quantity");
          if (!(id instanceof Number) || !(quantity instanceof Number)) {
            continue;
          }
          int itemId = ((Number) id).intValue();
          long qty = ((Number) quantity).longValue();
          if (itemId <= 0 || qty <= 0) {
            continue;
          }
          Map<String, Object> item = new LinkedHashMap<>();
          item.put("id", itemId);
          item.put("quantity", qty);
          items.add(item);
          if (!SKIPPED_CATEGORIES.contains(category)) {
            merged.merge(itemId, qty, Long::sum);
          }
        }
      }

      Map<String, Object> out = new LinkedHashMap<>();
      out.put("category", category);
      out.put("name", String.valueOf(storage.get("name")));
      Object lastUpdated = storage.get("lastUpdated");
      out.put("lastUpdated", lastUpdated instanceof Number ? ((Number) lastUpdated).longValue() : -1L);
      out.put("items", items);
      storages.add(out);
    }
    return new StoragePayload(Collections.unmodifiableList(storages), fingerprintOf(merged));
  }

  /** The request body. playerName is null unless the user chose to send it. */
  Map<String, Object> toRequestBody(String playerName, String clientVersion) {
    Map<String, Object> body = new HashMap<>();
    body.put("version", FORMAT_VERSION);
    body.put("client", "bank-ledger-uploader/" + clientVersion);
    body.put("storages", storages);
    if (playerName != null && !playerName.isEmpty()) {
      body.put("player", playerName);
    }
    return body;
  }

  /** A hash of the merged bank (id to total quantity, kept categories only). */
  String fingerprint() {
    return fingerprint;
  }

  boolean isEmpty() {
    return storages.isEmpty();
  }

  private static String fingerprintOf(TreeMap<Integer, Long> merged) {
    StringBuilder canonical = new StringBuilder();
    merged.forEach((id, qty) -> canonical.append(id).append(':').append(qty).append(';'));
    try {
      byte[] digest =
          MessageDigest.getInstance("SHA-256").digest(canonical.toString().getBytes(StandardCharsets.UTF_8));
      StringBuilder hex = new StringBuilder();
      for (byte b : digest) {
        hex.append(String.format("%02x", b));
      }
      return hex.toString();
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException(e); // SHA-256 is always present
    }
  }
}

package dev.bankledger.uploader;

/**
 * Spaces uploads out. Going back and forth between the bank and the Grand Exchange, or the bank
 * and a trip, changes the bank on nearly every close, and each change was its own upload - twenty
 * in a session that is really one. After a stored upload, further changes wait out a cooldown;
 * the latest bank is then sent once when it ends, so nothing is lost, only merged.
 *
 * <p>Pure and thread-safe (the plugin touches it from the client thread, OkHttp's thread and the
 * scheduler).
 */
final class UploadThrottle {
  private boolean anyStored;
  private long lastStoredAt;
  private boolean held;

  /** Whether an upload may go now. */
  synchronized boolean allows(long now, long cooldownMs) {
    return !anyStored || now - lastStoredAt >= cooldownMs;
  }

  /** A changed bank arrived during the cooldown: send it when the cooldown ends. */
  synchronized void hold() {
    held = true;
  }

  /** The bank is back to what was last sent: nothing is waiting any more. */
  synchronized void release() {
    held = false;
  }

  /** An upload was stored: start the cooldown. */
  synchronized void stored(long now) {
    anyStored = true;
    lastStoredAt = now;
    held = false;
  }

  /** A held change whose cooldown has ended, so it should be fetched and sent now. */
  synchronized boolean due(long now, long cooldownMs) {
    return held && allows(now, cooldownMs);
  }

  synchronized boolean isHolding() {
    return held;
  }

  synchronized void reset() {
    anyStored = false;
    held = false;
  }
}

package dev.bankledger.uploader;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * What is locked inside Grand Exchange offers, as a storage to upload alongside DWMS's.
 *
 * <p>Items listed for sale and coins committed to buy offers have left the bank, and DWMS doesn't
 * track them (its "Grand Exchange" storage only reads refunded coins off the collection window), so
 * an upload made with full GE slots understated the bank. This counts only what cannot also be in
 * the bank:
 *
 * <ul>
 *   <li>buy offers, active or cancelled: the coins for the part not yet bought, at the offer price;
 *   <li>sell offers, active or cancelled: the items not yet sold.
 * </ul>
 *
 * <p>The filled part of an offer (items bought, coins received) is left out: it may be waiting in
 * the collection box or already collected into the bank, and the client can't tell which, so
 * counting it could count it twice. It is counted once it is collected.
 *
 * <p>Pure: offers arrive as {@link Offer} values, not RuneLite types, so it is unit tested alone.
 */
final class GrandExchangeHoldings {
  static final String CATEGORY = "ge";
  static final String NAME = "Grand Exchange offers";
  static final int COINS = 995;

  /** One GE slot, copied from RuneLite's GrandExchangeOffer. state is the enum's name. */
  static final class Offer {
    final String state;
    final int itemId;
    final long price;
    final int totalQuantity;
    final int quantitySold;

    Offer(String state, int itemId, long price, int totalQuantity, int quantitySold) {
      this.state = state;
      this.itemId = itemId;
      this.price = price;
      this.totalQuantity = totalQuantity;
      this.quantitySold = quantitySold;
    }
  }

  private GrandExchangeHoldings() {}

  /** {id, quantity} items locked in the offers, merged by id; empty if nothing is. */
  static List<Map<String, Object>> items(List<Offer> offers) {
    TreeMap<Integer, Long> held = new TreeMap<>();
    for (Offer o : offers) {
      if (o == null || o.itemId <= 0 || o.totalQuantity <= 0) {
        continue;
      }
      long unfilled = Math.max(0, (long) o.totalQuantity - o.quantitySold);
      if (unfilled == 0) {
        continue;
      }
      switch (o.state) {
        case "BUYING":
        case "CANCELLED_BUY":
          if (o.price > 0) {
            held.merge(COINS, unfilled * o.price, Long::sum);
          }
          break;
        case "SELLING":
        case "CANCELLED_SELL":
          held.merge(o.itemId, unfilled, Long::sum);
          break;
        default:
          // EMPTY, BOUGHT, SOLD: nothing locked.
          break;
      }
    }
    List<Map<String, Object>> items = new ArrayList<>();
    held.forEach(
        (id, qty) -> {
          Map<String, Object> item = new LinkedHashMap<>();
          item.put("id", id);
          item.put("quantity", qty);
          items.add(item);
        });
    return items;
  }

  /** The storage entry in the shape DWMS's response uses. */
  static Map<String, Object> storage(List<Map<String, Object>> items, long now) {
    Map<String, Object> storage = new LinkedHashMap<>();
    storage.put("category", CATEGORY);
    storage.put("name", NAME);
    storage.put("lastUpdated", now);
    storage.put("items", items);
    return storage;
  }

  /** DWMS's own GE storage, which this replaces (it overlaps on refunded coins). */
  static boolean isDwmsGrandExchange(Map<?, ?> storage) {
    return "coins".equals(String.valueOf(storage.get("category")))
        && "Grand Exchange".equals(String.valueOf(storage.get("name")));
  }
}
